import"./chunk-VC46IEJQ.js";var e=(a,r)=>({en:a,zh:r}),t=(a,r,s,n,h,i,d,l,o)=>({name:a,desc:r,tour:s,...o?{spoiler:o}:{},source:{confidence:n,refs:h,book:i,unknown:d,interpretation:l}}),c={id:"the-twins",intro:e("Two identical castles face each other across the Green Fork, joined by a great stone bridge with the Water Tower at its middle. The Freys hold the only crossing for hundreds of miles, and they charge for it.","\u4E24\u5EA7\u4E00\u6A21\u4E00\u6837\u7684\u57CE\u5821\u9694\u7740\u7EFF\u53C9\u6CB3\u76F8\u671B\uFF0C\u4E00\u5EA7\u5DE8\u5927\u7684\u77F3\u6865\u5C06\u5B83\u4EEC\u8FDE\u5728\u4E00\u8D77\uFF0C\u6865\u4E2D\u592E\u77D7\u7ACB\u7740\u6C34\u5854\u3002\u4F5B\u96F7\u5BB6\u65CF\u628A\u5B88\u7740\u65B9\u5706\u6570\u767E\u91CC\u5185\u552F\u4E00\u7684\u6E21\u53E3\uFF0C\u5E76\u4EE5\u6B64\u6536\u53D6\u8FC7\u8DEF\u8D39\u3002"),notes:e("From the novels: two matching castles on the east and west banks of the Green Fork, a stone bridge between them with the Water Tower at its centre, moats, barbicans and portcullises, and House Frey's toll on the crossing. Invented here: all dimensions, walls, keeps and the arch shape. For framing, the scene turns the river to run across the view, so the castles sit at top and bottom rather than east and west.","\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u7EFF\u53C9\u6CB3\u4E1C\u897F\u4E24\u5CB8\u5404\u6709\u4E00\u5EA7\u76F8\u540C\u7684\u57CE\u5821\uFF0C\u4E2D\u95F4\u4EE5\u77F3\u6865\u76F8\u8FDE\uFF0C\u6865\u5FC3\u7ACB\u7740\u6C34\u5854\uFF1B\u4E24\u5821\u5404\u6709\u62A4\u57CE\u6CB3\u3001\u5916\u5821\u4E0E\u94C1\u95F8\u95E8\uFF1B\u4F5B\u96F7\u5BB6\u65CF\u5728\u6E21\u53E3\u5F81\u6536\u8FC7\u8DEF\u8D39\u3002\u672C\u573A\u666F\u81EA\u884C\u8BBE\u8BA1\uFF1A\u4E00\u5207\u5C3A\u5BF8\u3001\u57CE\u5899\u3001\u4E3B\u5821\u4E0E\u6865\u62F1\u5F62\u72B6\u3002\u4E3A\u4FBF\u4E8E\u53D6\u666F\uFF0C\u573A\u666F\u8BA9\u6CB3\u6D41\u6A2A\u8D2F\u753B\u9762\uFF0C\u4E24\u5821\u56E0\u6B64\u4E00\u4E0A\u4E00\u4E0B\uFF0C\u800C\u975E\u4E00\u4E1C\u4E00\u897F\u3002"),tour:["green-fork","bridge","water-tower","north-castle","north-barbican","south-castle","south-barbican","moat-channels","kingsroad"],sources:[{ref:"agot",checked:"memory",note:e("Catelyn negotiates the crossing with Lord Walder; the identical castles, the Water Tower and the toll are recalled from those chapters, not re-read.","\u51EF\u7279\u7433\u4E0E\u74E6\u5FB7\u5927\u4EBA\u8C08\u5224\u501F\u9053\uFF1B\u4E24\u5EA7\u76F8\u540C\u7684\u57CE\u5821\u3001\u6C34\u5854\u4E0E\u8FC7\u8DEF\u8D39\u5747\u51ED\u5BF9\u8FD9\u4E9B\u7AE0\u8282\u7684\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002")},{ref:"asos",checked:"memory",note:e("The Twins are revisited in the third book; recalled in outline only.","\u7B2C\u4E09\u5377\u91CD\u56DE\u5B6A\u6CB3\u57CE\uFF1B\u4EC5\u51ED\u8BB0\u5FC6\u8BB0\u5F97\u6897\u6982\u3002")},{ref:"awoiaf",checked:"search-snippet",note:e("Search summaries confirm identical castles on the east and west banks, high curtain walls, deep moats, barbicans and portcullises, a bridge wide enough for two wagons abreast, the Water Tower with arrow slits and murder holes, and the toll. Pages not fetched.","\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF1A\u4E1C\u897F\u4E24\u5CB8\u5404\u6709\u4E00\u5EA7\u76F8\u540C\u7684\u57CE\u5821\uFF0C\u57CE\u5899\u9AD8\u8038\uFF0C\u62A4\u57CE\u6CB3\u6DF1\u9614\uFF0C\u8BBE\u6709\u5916\u5821\u4E0E\u94C1\u95F8\u95E8\uFF1B\u77F3\u6865\u5BBD\u53EF\u5E76\u884C\u4E24\u8F86\u5927\u8F66\uFF1B\u6C34\u5854\u8BBE\u6709\u7BAD\u5B54\u4E0E\u6740\u4EBA\u5B54\uFF1B\u6E21\u53E3\u6536\u53D6\u8FC7\u8DEF\u8D39\u3002\u9875\u9762\u672A\u6293\u53D6\u3002")}],landmarks:{"north-castle":t(e("East Castle","\u4E1C\u5821"),e("One of the two identical twins: grey curtain walls, towers and a keep from which the bridge springs.","\u4E00\u5BF9\u5B6A\u751F\u57CE\u5821\u4E4B\u4E00\uFF1A\u7070\u8272\u57CE\u5899\u3001\u5854\u697C\uFF0C\u4EE5\u53CA\u5927\u6865\u7531\u6B64\u8D77\u62F1\u7684\u4E3B\u5821\u3002"),e("One twin guards the east bank; the bridge springs from within its walls.","\u4E00\u5EA7\u57CE\u5821\u5B88\u7740\u4E1C\u5CB8\uFF0C\u5927\u6865\u4FBF\u4ECE\u5B83\u7684\u57CE\u5899\u5185\u8D77\u62F1\u3002"),"high",["agot","awoiaf"],e("A castle on the east bank of the Green Fork, identical to its twin, with its own walls, moat, barbican and portcullis.","\u7EFF\u53C9\u6CB3\u4E1C\u5CB8\u7684\u57CE\u5821\uFF0C\u4E0E\u5BF9\u5CB8\u90A3\u5EA7\u4E00\u6A21\u4E00\u6837\uFF0C\u5404\u6709\u57CE\u5899\u3001\u62A4\u57CE\u6CB3\u3001\u5916\u5821\u4E0E\u94C1\u95F8\u95E8\u3002"),e("Its interior layout, wall height and garrison.","\u5185\u90E8\u5E03\u5C40\u3001\u57CE\u5899\u9AD8\u5EA6\u4E0E\u5B88\u519B\u89C4\u6A21\u3002"),e("A walled square with a keep, hall and toll-house; blue roofs echo the Frey colours. Placed on the upper bank of the scene.","\u65B9\u5F62\u57CE\u5899\u5185\u8BBE\u4E3B\u5821\u3001\u5927\u5385\u4E0E\u6536\u8D39\u5C4B\uFF1B\u84DD\u8272\u5C4B\u9876\u53D6\u81EA\u4F5B\u96F7\u5BB6\u65CF\u7684\u5BB6\u8272\u3002\u7F6E\u4E8E\u573A\u666F\u4E2D\u4E0A\u65B9\u7684\u6CB3\u5CB8\u3002"),e("In the third book a wedding feast at the Twins becomes the Red Wedding.","\u7B2C\u4E09\u5377\u4E2D\uFF0C\u5B6A\u6CB3\u57CE\u7684\u4E00\u573A\u5A5A\u5BB4\u917F\u6210\u4E86\u201C\u8840\u8272\u5A5A\u793C\u201D\u3002")),"south-castle":t(e("West Castle","\u897F\u5821"),e("The other twin, a mirror of the first, on the bank toward Riverrun and the west.","\u53E6\u4E00\u5EA7\u5B6A\u751F\u57CE\u5821\uFF0C\u4E0E\u4E1C\u5821\u5982\u51FA\u4E00\u8F99\uFF0C\u5750\u843D\u5728\u901A\u5F80\u5954\u6D41\u57CE\u4E0E\u897F\u65B9\u7684\u4E00\u5CB8\u3002"),e("Its twin holds the west bank and the roads toward Riverrun.","\u5B83\u7684\u5B6A\u751F\u5144\u5F1F\u5B88\u7740\u897F\u5CB8\u548C\u901A\u5F80\u5954\u6D41\u57CE\u7684\u9053\u8DEF\u3002"),"high",["agot","awoiaf"],e("A matching castle on the west bank.","\u897F\u5CB8\u4E00\u5EA7\u4E0E\u4E1C\u5821\u76F8\u540C\u7684\u57CE\u5821\u3002"),e("Whether the two differ inside.","\u4E24\u5EA7\u57CE\u5821\u5185\u90E8\u662F\u5426\u6709\u522B\u3002"),e("An exact mirror of the other castle, placed on the lower bank of the scene.","\u4E0E\u53E6\u4E00\u5EA7\u5B8C\u5168\u955C\u50CF\uFF0C\u7F6E\u4E8E\u573A\u666F\u4E2D\u4E0B\u65B9\u7684\u6CB3\u5CB8\u3002")),bridge:t(e("The Bridge","\u5927\u6865"),e("A great bridge of grey stone, wide enough for two wagons abreast, running from one castle to the other.","\u4E00\u5EA7\u7070\u77F3\u5DE8\u6865\uFF0C\u5BBD\u53EF\u5E76\u884C\u4E24\u8F86\u5927\u8F66\uFF0C\u4ECE\u4E00\u5EA7\u57CE\u5821\u901A\u5411\u53E6\u4E00\u5EA7\u3002"),e("The only crossing for hundreds of miles: two wagons wide and always watched.","\u65B9\u5706\u6570\u767E\u91CC\u5185\u552F\u4E00\u7684\u6E21\u53E3\uFF1A\u5BBD\u53EF\u5E76\u884C\u4E24\u8F66\uFF0C\u65F6\u523B\u6709\u4EBA\u76EF\u7740\u3002"),"high",["agot","awoiaf"],e("A stone bridge joins the two castles and is the crossing of the Green Fork.","\u4E00\u5EA7\u77F3\u6865\u8FDE\u63A5\u4E24\u5821\uFF0C\u662F\u7EFF\u53C9\u6CB3\u4E0A\u7684\u6E21\u53E3\u3002"),e("The number of arches, the span and the height.","\u6865\u62F1\u6570\u91CF\u3001\u8DE8\u5EA6\u4E0E\u9AD8\u5EA6\u3002"),e("A single high arch with parapets; the deck sits about 13 m above the banks.","\u5355\u62F1\u9AD8\u6865\uFF0C\u4E24\u4FA7\u8BBE\u62A4\u5899\uFF1B\u6865\u9762\u7EA6\u9AD8\u51FA\u6CB3\u5CB8\u5341\u4E09\u7C73\u3002")),"water-tower":t(e("Water Tower","\u6C34\u5854"),e("The tower at the bridge's midpoint, with arrow slits, murder holes and portcullises; every traveller passes through it.","\u6865\u4E2D\u592E\u7684\u5854\u697C\uFF0C\u8BBE\u6709\u7BAD\u5B54\u3001\u6740\u4EBA\u5B54\u4E0E\u94C1\u95F8\u95E8\uFF0C\u6240\u6709\u8FC7\u5BA2\u90FD\u987B\u4ECE\u5854\u4E0B\u7A7F\u8FC7\u3002"),e("The Water Tower sits mid-span: no one crosses without passing beneath it.","\u6C34\u5854\u5750\u9547\u6865\u5FC3\uFF1A\u8FC7\u6865\u8005\u65E0\u4E0D\u4ECE\u5B83\u811A\u4E0B\u7ECF\u8FC7\u3002"),"high",["agot","awoiaf"],e("A tower in the middle of the bridge guards the crossing, with arrow slits, murder holes and portcullises.","\u5927\u6865\u4E2D\u592E\u6709\u5EA7\u5854\u697C\u627C\u5B88\u6E21\u53E3\uFF0C\u8BBE\u6709\u7BAD\u5B54\u3001\u6740\u4EBA\u5B54\u4E0E\u94C1\u95F8\u95E8\u3002"),e("Its floor plan and how it is used inside.","\u5185\u90E8\u5E03\u5C40\u4E0E\u7528\u9014\u3002"),e("A square tower with a pyramid roof and an iron portcullis on each side.","\u4E00\u5EA7\u56DB\u5761\u5C16\u9876\u7684\u65B9\u5854\uFF0C\u4E24\u4FA7\u5404\u8BBE\u4E00\u9053\u94C1\u95F8\u95E8\u3002")),"north-barbican":t(e("East Barbican","\u4E1C\u5916\u5821"),e("The fortified gate of the east castle, where travellers wait and the toll is taken.","\u4E1C\u5821\u7684\u8BBE\u9632\u57CE\u95E8\uFF0C\u65C5\u4EBA\u5728\u6B64\u5019\u884C\uFF0C\u7F34\u7EB3\u8FC7\u8DEF\u8D39\u3002"),e("At the gate, travellers pay for the right to cross.","\u5728\u57CE\u95E8\u524D\uFF0C\u65C5\u4EBA\u8981\u4E3A\u8FC7\u6CB3\u4ED8\u94B1\u3002"),"medium",["agot","awoiaf"],e("Each castle has a barbican and portcullis; the Freys levy a toll on the crossing.","\u4E24\u5821\u5404\u6709\u5916\u5821\u4E0E\u94C1\u95F8\u95E8\uFF1B\u4F5B\u96F7\u5BB6\u65CF\u5BF9\u8FC7\u6CB3\u8005\u5F81\u6536\u8FC7\u8DEF\u8D39\u3002"),e("How the toll is collected and what it costs.","\u8FC7\u8DEF\u8D39\u5982\u4F55\u6536\u53D6\u3001\u6536\u591A\u5C11\u3002"),e("A toll-house and barrier by the gate are invented.","\u57CE\u95E8\u65C1\u7684\u6536\u8D39\u5C4B\u4E0E\u62E6\u6746\u4E3A\u865A\u6784\u3002")),"south-barbican":t(e("West Barbican","\u897F\u5916\u5821"),e("The matching gate of the west castle.","\u897F\u5821\u5BF9\u79F0\u7684\u8BBE\u9632\u57CE\u95E8\u3002"),e("The west gate opens toward Riverrun.","\u897F\u95E8\u671D\u5411\u5954\u6D41\u57CE\u7684\u65B9\u5411\u3002"),"medium",["agot","awoiaf"],e("A barbican and gate guard each castle.","\u4E24\u5821\u5404\u6709\u5916\u5821\u4E0E\u57CE\u95E8\u628A\u5B88\u3002"),e("Whether it keeps its own toll post.","\u662F\u5426\u53E6\u8BBE\u6536\u8D39\u5904\u3002"),e("Mirrored from the east gate.","\u7167\u4E1C\u5916\u5821\u955C\u50CF\u800C\u6210\u3002")),"green-fork":t(e("The Green Fork","\u7EFF\u53C9\u6CB3"),e("The northern branch of the Trident, swift and deep where it runs between the castles.","\u4E09\u53C9\u621F\u6CB3\u7684\u5317\u9762\u652F\u6D41\uFF0C\u6D41\u7ECF\u4E24\u5821\u4E4B\u95F4\u65F6\u6C34\u6025\u4E14\u6DF1\u3002"),e("Swift and deep, the Green Fork runs between the twins.","\u7EFF\u53C9\u6CB3\u6C34\u6025\u4E14\u6DF1\uFF0C\u4ECE\u4E24\u5EA7\u57CE\u5821\u4E4B\u95F4\u5954\u6D41\u800C\u8FC7\u3002"),"high",["agot","maps"],e("The Green Fork flows south out of the Neck to join the Trident; at the Twins it runs swift and deep.","\u7EFF\u53C9\u6CB3\u81EA\u9888\u6CFD\u5411\u5357\u6D41\uFF0C\u6C47\u5165\u4E09\u53C9\u621F\u6CB3\uFF1B\u5728\u5B6A\u6CB3\u57CE\u4E00\u5E26\u6C34\u6025\u4E14\u6DF1\u3002"),e("Its width here and how far boats can travel on it.","\u6B64\u5904\u7684\u6CB3\u5BBD\uFF0C\u4EE5\u53CA\u8239\u53EA\u80FD\u822A\u884C\u591A\u8FDC\u3002"),e("The boats and reed banks are invented.","\u8239\u53EA\u4E0E\u82A6\u82C7\u5CB8\u4E3A\u865A\u6784\u3002")),"moat-channels":t(e("Moat Channels","\u62A4\u57CE\u6CB3"),e("Moats fed from the river ring each castle, making each an island.","\u5F15\u6CB3\u6C34\u6CE8\u5165\u7684\u62A4\u57CE\u6CB3\u73AF\u7ED5\u4E24\u5821\uFF0C\u4F7F\u4E4B\u5404\u6210\u5B64\u5C9B\u3002"),e("Water from the river rings each castle.","\u5F15\u6765\u7684\u6CB3\u6C34\u73AF\u7ED5\u7740\u6BCF\u4E00\u5EA7\u57CE\u5821\u3002"),"medium",["agot","awoiaf"],e("Each castle has deep moats; reference summaries say they are fed from the river.","\u4E24\u5821\u5404\u6709\u6DF1\u9614\u7684\u62A4\u57CE\u6CB3\uFF1B\u53C2\u8003\u8D44\u6599\u6458\u8981\u79F0\u5176\u5F15\u81EA\u6CB3\u6C34\u3002"),e("Their layout and depth.","\u5E03\u5C40\u4E0E\u6DF1\u5EA6\u3002"),e("A rectangle of water on three sides of each castle.","\u6BCF\u5EA7\u57CE\u5821\u4E09\u9762\u73AF\u7ED5\u7684\u77E9\u5F62\u6C34\u9053\u3002")),kingsroad:t(e("Approach Roads","\u8FC7\u6CB3\u5927\u9053"),e("Roads from both banks converge on the castle gates; wagons and riders queue to cross.","\u4E24\u5CB8\u9053\u8DEF\u6C47\u5411\u57CE\u95E8\uFF0C\u5927\u8F66\u4E0E\u9A91\u624B\u6392\u961F\u7B49\u5019\u8FC7\u6CB3\u3002"),e("Every road to the crossing runs straight into Frey gates.","\u51E1\u901A\u5F80\u6E21\u53E3\u7684\u8DEF\uFF0C\u90FD\u5F84\u76F4\u901A\u8FDB\u4F5B\u96F7\u5BB6\u7684\u57CE\u95E8\u3002"),"medium",["agot","maps"],e("The Twins command the only crossing of the Green Fork for hundreds of miles, a vital link between the North and the western riverlands; the kingsroad itself runs east of the river.","\u5B6A\u6CB3\u57CE\u627C\u5B88\u7EFF\u53C9\u6CB3\u4E0A\u65B9\u5706\u6570\u767E\u91CC\u552F\u4E00\u7684\u6E21\u53E3\uFF0C\u662F\u5317\u5883\u901A\u5F80\u6CB3\u95F4\u5730\u897F\u90E8\u7684\u8981\u9053\uFF1B\u56FD\u738B\u5927\u9053\u672C\u8EAB\u5219\u5728\u6CB3\u4E1C\u3002"),e("The exact course of the roads near the castles.","\u57CE\u5821\u9644\u8FD1\u9053\u8DEF\u7684\u786E\u5207\u8D70\u5411\u3002"),e("A straight cobbled road on each side; this is the crossing road, not the kingsroad.","\u4E24\u5CB8\u5404\u4E00\u6761\u7B14\u76F4\u7684\u77F3\u677F\u8DEF\uFF1B\u8FD9\u662F\u8FC7\u6CB3\u7684\u9053\u8DEF\uFF0C\u5E76\u975E\u56FD\u738B\u5927\u9053\u3002"))}};export{c as default};
